import Foundation

/// Copy chosen at runtime (enum titles, composed messages, UIKit labels). SwiftUI literals localize
/// themselves; the catalog for both is generated by scripts/scanner-strings.
func sc(_ key: String) -> String { String(localized: String.LocalizationValue(key), bundle: .main) }

/// A count sentence with String Catalog plural variants, keyed `scanner.count.<key>`.
func scCount(_ count: Int, key: String) -> String {
    String.localizedStringWithFormat(NSLocalizedString("scanner.count." + key, bundle: .main, comment: "Scanner count, with plural variants"), count)
}
